import sys


def main():
    text = sys.stdin.read()
    config, _, queries = text.partition("===\n")
    data = {}
    current_section = None  # To track the current section

    for line in config.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("["):
            # Section header
            section_name = line[1:-1].strip()
            current_section = section_name.lower()
            data.setdefault(current_section, {})
        elif "=" in line:
            # Key-value line
            key, value = line.split("=", 1)
            key = key.strip().lower()
            value = value.strip()

            # Handle quoted values
            if value.startswith('"'):
                end_quote = value.find('"', 1)
                if end_quote != -1:
                    value = value[1 : end_quote]
                else:
                    value = ""  # Invalid, but keep as empty string
            else:
                # Remove comments after ;
                comment_index = value.find(';')
                if comment_index != -1:
                    value = value[:comment_index].rstrip()

            data[current_section][key] = value

    for query_line in queries.splitlines():
        query_line = query_line.strip()
        if not query_line:
            continue
        parts = query_line.split(".", 1)
        if len(parts) != 2:
            print("NOT FOUND")
            continue
        section, key = parts
        section = section.strip().lower()
        key = key.strip().lower()

        value = data.get(section, {}).get(key, "NOT FOUND")
        print(value)


if __name__ == "__main__":
    main()
